    [Fact]
    public void Q500_coda_batch13_hook_participates_economy()
    {
        var g = Game.New(seed: 1150);
        LabState rival = g.Rival("openaye");
        rival.Models.Add(Released(g, 540));
        rival.Cash = -18_000;
        Finance.Earn(g.Me, LedgerLine.CapitalIn, 76_000_000);
